const config = $('Config').first().json.config;

let liste = KANDIDATEN.filter(k => /^\d+$/.test(String(k.bestellnummer))
                                && String(k.mollieId).startsWith('ord_'));

// Whitelist fuer kontrollierte Laeufe
const weiss = (config.nurBestellnummern || [])
  .map(v => String(v ?? '').trim()).filter(Boolean);
if (weiss.length) liste = liste.filter(k => weiss.includes(String(k.bestellnummer)));

// Faellige zuerst - die Verfallsfristen laufen von hinten ab
liste = [...liste].sort((a, b) =>
  String(a.expiresAt ?? '9999').localeCompare(String(b.expiresAt ?? '9999')));

if (config.testLimit > 0) liste = liste.slice(0, config.testLimit);

const tage = v => v ? Math.floor((new Date(v).getTime() - Date.now()) / 86400000) : null;

// Feldnamen wie bisher, damit die nachgelagerten Nodes unveraendert bleiben.
return liste.map(k => ({ json: {
  bestellnummer:        String(k.bestellnummer),
  mollieId:             k.mollieId,
  mollieOrderStatus:    k.status ?? null,
  mollieBetrag:         k.betrag ?? null,
  mollieBereitsErfasst: k.erfasst ?? null,
  expiresAt:            k.expiresAt ?? null,
  restfristTage:        tage(k.expiresAt),
  mengeVersendbar:      k.versendbar ?? null,
  listeGesamt:          KANDIDATEN.length,
  runId: $execution.id
}}));

// PHASE 2 – Bestellnummern zu SQL-Batches buendeln.
const config = $('Config').first().json.config;
const alle = $input.all().map(i => i.json);
const g = Math.max(1, Math.min(Number(config.jtlBatchGroesse) || 200, 1000));

const out = [];
for (let i = 0; i < alle.length; i += g) {
  const teil = alle.slice(i, i + g);
  out.push({ json: {
    batchIndex: out.length,
    anzahl: teil.length,
    bestellnummern: teil.map(t => t.bestellnummer)
  }});
}
return out;

// PHASE 2 – Zeilen durchreichen; die Sammlung uebernimmt der done-Ausgang
// von 'Loop JTL'. Leere Ergebnisse fallen hier raus.
return $input.all()
  .filter(i => i.json && i.json.kLieferschein !== undefined && i.json.kLieferschein !== null);

// PHASE 3 – Positionszeilen zu einem Item je LIEFERSCHEIN buendeln
// und die Mollie-Daten des Kandidaten anhaengen.
const config = $('Config').first().json.config;
const rows = $input.all().map(i => i.json)
  .filter(r => r && r.kLieferschein !== undefined && r.kLieferschein !== null);

// Mollie-Bezug aus Phase 1: ord_-ID, Betrag, Frist
const mollie = new Map();
for (const k of $('Kandidaten aufbereiten').all().map(i => i.json)) {
  mollie.set(String(k.bestellnummer), k);
}

const txt = v => String(v ?? '').trim();
const map = new Map();

for (const r of rows) {
  const key = Number(r.kLieferschein);
  if (!map.has(key)) {
    const nr = txt(r[config.bestellnummerFeld]);
    const m  = mollie.get(nr) || {};
    map.set(key, {
      kLieferschein:   key,
      cLieferscheinNr: txt(r.cLieferscheinNr) || null,
      dVersendet:      r.dVersendet ?? null,
      trackingNummer:  txt(r.cIdentCode) || null,
      trackingCarrier: txt(r.Carrier) || null,
      kBestellung:     Number(r.kBestellung),
      bestellnummer:   nr,
      shopifyOrderName: config.shopifyNamePrefix + nr,
      // --- aus dem Mollie-Scan ---
      mollieId:             m.mollieId ?? null,
      mollieOrderStatus:    m.mollieOrderStatus ?? null,
      mollieBetrag:         m.mollieBetrag ?? null,
      mollieBereitsErfasst: m.mollieBereitsErfasst ?? null,
      mollieExpiresAt:      m.expiresAt ?? null,
      restfristTage:        m.restfristTage ?? null,
      positionen: [],
      runId: $execution.id
    });
  }

  const ls    = map.get(key);
  const art   = txt(r[config.artikelnummerFeld]);
  const menge = Number(r.fMengeGeliefert) || 0;
  const da    = ls.positionen.find(p => p.cArtNr === art);
  if (da) {
    da.mengeGeliefert += menge;
    da.mengeBestellt  += Number(r.nMengeBestellt) || 0;
    da.kBestellPos.push(Number(r.kBestellPos));
  } else {
    ls.positionen.push({
      cArtNr: art,
      cArtikelname: txt(r.cArtikelname) || null,
      mengeGeliefert: menge,
      mengeBestellt: Number(r.nMengeBestellt) || 0,
      kBestellPos: [Number(r.kBestellPos)]
    });
  }
}

// Chronologisch – entscheidend fuer die Restmengen-Reihenfolge
return [...map.values()]
  .sort((a, b) => String(a.dVersendet).localeCompare(String(b.dVersendet)) ||
                  a.kLieferschein - b.kLieferschein)
  .map(json => ({ json }));

// Lieferscheine nach Bestellung gruppieren, dann Bestellungen in Batches
// schneiden – ein GraphQL-Lookup je Batch.
const config = $('Config').first().json.config;
const alle   = $input.all().map(i => i.json);

const perOrder = new Map();
for (const ls of alle) {
  const k = ls.shopifyOrderName;
  if (!perOrder.has(k)) {
    perOrder.set(k, {
      shopifyOrderName: k,
      bestellnummer:    ls.bestellnummer,
      kBestellung:      ls.kBestellung,
      lieferscheine:    []
    });
  }
  perOrder.get(k).lieferscheine.push(ls);
}

// Innerhalb der Bestellung: Lieferscheine in Versandreihenfolge.
for (const o of perOrder.values()) {
  o.lieferscheine.sort((a, b) =>
    String(a.dVersendet).localeCompare(String(b.dVersendet)) ||
    a.kLieferschein - b.kLieferschein);
  o.anzahlLieferscheine = o.lieferscheine.length;
}

const bestellungen = [...perOrder.values()];
const groesse = Math.max(1, Math.min(Number(config.batchGroesse) || 25, 100));

const out = [];
for (let i = 0; i < bestellungen.length; i += groesse) {
  const teil = bestellungen.slice(i, i + groesse);
  out.push({ json: {
    batchIndex:          out.length,
    anzahlBestellungen:  teil.length,
    anzahlLieferscheine: teil.reduce((s, o) => s + o.lieferscheine.length, 0),
    bestellungen:        teil
  }});
}
return out;

// Sammel-Lookup je Batch. Wir brauchen jetzt drei Dinge pro Bestellung:
//   1. offene FulfillmentOrder-Positionen mit sku + remainingQuantity
//   2. bereits hinterlegte Trackingnummern (Doppelt-Erkennung)
//   3. den aktuellen Fulfillment-Status
const config = $('Config').first().json.config;
// Der Batch kommt jetzt nicht mehr direkt aus dem Eingang – dort liegt
// die Antwort des Token-Nodes. Deshalb gezielt aus der Schleife holen.
const batch  = $('Loop Over Batches').first().json;

const q = batch.bestellungen.map(o => 'name:' + o.shopifyOrderName).join(' OR ');

const query = `query($q: String!) {
  orders(first: ${Math.max(1, batch.anzahlBestellungen)}, query: $q) {
    edges { node {
      id
      name
      closed
      cancelledAt
      displayFulfillmentStatus
      fulfillments(first: ${config.fulfillmentsProBestellung}) {
        id
        status
        createdAt
        trackingInfo(first: 5) { number company }
      }
      fulfillmentOrders(first: ${config.foProBestellung}) {
        edges { node {
          id
          status
          lineItems(first: ${config.lineItemsProFo}) {
            edges { node {
              id
              sku
              productTitle
              variantTitle
              totalQuantity
              remainingQuantity
              lineItem { id sku name }
            } }
          }
        } }
      }
    } }
  }
}`;

return [{ json: {
  batchIndex:          batch.batchIndex,
  anzahlBestellungen:  batch.anzahlBestellungen,
  anzahlLieferscheine: batch.anzahlLieferscheine,
  bestellungen:        batch.bestellungen,
  gqlBody: JSON.stringify({ query, variables: { q } })
}}];

// KERN: Zuordnung JTL-Lieferscheinposition -> Shopify FulfillmentOrder-Position.
// Umschaltbar ueber config.skuMatching:
//   true  -> ausschliesslich ueber sku
//   false -> ausschliesslich ueber Titel (exakt, dann normalisiert)
// Migrierte Bestellungen tragen (noch) KEINE sku auf Positionsebene (Matrixify-Import).
// Ausgabe: ein Item pro LIEFERSCHEIN mit fertigem Plan (noch ohne Schreib-Call).
const config = $('Config').first().json.config;
const src    = $('Query bauen (Orders-Lookup)').first().json;
const resp   = $input.first().json;

const FO_OFFEN  = ['OPEN', 'IN_PROGRESS', 'SCHEDULED'];
const normName  = s => String(s ?? '').replace(/^#/, '').trim();
const normSku   = s => String(s ?? '').trim().toUpperCase();
const alsListe  = v => Array.isArray(v) ? v : (v?.edges || []).map(e => e.node);

// Stufe 1: nur trimmen + Kleinschreibung
const titelExakt = s => String(s ?? '').trim().toLowerCase();
// Stufe 2: Diakritika weg, alles Nicht-Alphanumerische zu einem Leerzeichen
// Positionen, die in Shopify systematisch nicht existieren (z. B. Versand-
// zuschlaege, die JTL als Artikel fuehrt). Praefixvergleich, case-insensitiv.
const istIgnoriert = artNr => {
  const a = String(artNr ?? '').trim().toUpperCase();
  if (!a) return false;
  return (config.ignorierteArtikelNr || [])
    .map(v => String(v ?? '').trim().toUpperCase())
    .filter(Boolean)
    .some(pre => a.startsWith(pre));
};

const titelNorm  = s => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

// --- Harter Fehler: ganzer Batch bekommt error -------------------------
if (resp?.error || resp?.errors) {
  const msg = 'Orders-Lookup fehlgeschlagen: ' +
              JSON.stringify(resp.error || resp.errors).slice(0, 500);
  const out = [];
  for (const best of src.bestellungen) {
    for (const ls of best.lieferscheine) {
      out.push({ json: { ...ls, batchIndex: src.batchIndex,
        shopifyStatus: 'error', shopifyAktion: 'skip', shopifyMessage: msg,
        zuordnung: [], lineItemsByFulfillmentOrder: [], matchStufen: [],
        summeGeliefert: ls.positionen.reduce((s, p) => s + p.mengeGeliefert, 0),
        summeZugeordnet: 0 } });
    }
  }
  return out;
}

const gefunden = new Map();
for (const e of (resp?.data?.orders?.edges || [])) {
  gefunden.set(normName(e.node.name), e.node);
}

const out = [];

for (const best of src.bestellungen) {
  const order = gefunden.get(normName(best.shopifyOrderName));

  // ---- Bestellung nicht in Shopify -----------------------------------
  if (!order) {
    for (const ls of best.lieferscheine) {
      out.push({ json: { ...ls, batchIndex: src.batchIndex,
        shopifyStatus: 'skipped_not_found', shopifyAktion: 'skip',
        shopifyMessage: 'Keine Shopify-Bestellung mit name=' + ls.shopifyOrderName,
        zuordnung: [], lineItemsByFulfillmentOrder: [], matchStufen: [],
        summeGeliefert: ls.positionen.reduce((s, p) => s + p.mengeGeliefert, 0),
        summeZugeordnet: 0 } });
    }
    continue;
  }

  // ---- vorhandene Trackingnummern (Doppelt-Erkennung) ----------------
  const trackingVorhanden = new Set();
  for (const f of alsListe(order.fulfillments)) {
    for (const t of alsListe(f?.trackingInfo)) {
      if (t?.number) trackingVorhanden.add(normSku(t.number));
    }
  }

  // ---- Restmengen-Pool aus den OFFENEN FulfillmentOrders -------------
  const pool      = [];
  const skusInFo  = new Set();
  const foPosAlle = [];
  const foStatusListe = [];

  for (const fe of (order.fulfillmentOrders?.edges || [])) {
    const fo = fe.node;
    foStatusListe.push(fo.status);
    for (const le of (fo.lineItems?.edges || [])) {
      const li    = le.node;
      const sku   = normSku(li.sku ?? li.lineItem?.sku);
      const titel = li.productTitle || li.lineItem?.name || null;
      if (sku) skusInFo.add(sku);
      foPosAlle.push({
        foStatus: fo.status, sku: sku || null, titel,
        variante: li.variantTitle || null,
        gesamt: Number(li.totalQuantity) || 0,
        rest:   Number(li.remainingQuantity) || 0
      });
      if (!FO_OFFEN.includes(fo.status)) continue;
      const rest = Number(li.remainingQuantity) || 0;
      if (rest <= 0) continue;
      pool.push({
        foId: fo.id, foliId: li.id, sku, titel, rest,
        tExakt: titelExakt(titel), tNorm: titelNorm(titel)
      });
    }
  }

  // ---- Kollisionsschutz Stufe 2 --------------------------------------
  // Normalisieren darf zwei verschiedene Artikel nicht auf denselben
  // Schluessel zusammenfallen lassen. Solche Schluessel werden gesperrt.
  const normGruppen = new Map();
  for (const k of pool) {
    if (!k.tNorm) continue;
    if (!normGruppen.has(k.tNorm)) normGruppen.set(k.tNorm, new Set());
    normGruppen.get(k.tNorm).add(k.tExakt);
  }
  const normGesperrt = new Set(
    [...normGruppen.entries()].filter(([, v]) => v.size > 1).map(([k]) => k));

  // ---- Lieferscheine in Versandreihenfolge abarbeiten ----------------
  for (const ls of best.lieferscheine) {
    const basis = { ...ls,
      batchIndex:                 src.batchIndex,
      shopifyOrderId:             order.id,
      shopifyOrderNameGefunden:   order.name,
      shopifyOrderClosed:         !!order.closed,
      shopifyStatusVorher:        order.displayFulfillmentStatus,
      anzahlFulfillmentOrders:    foStatusListe.length,
      fulfillmentOrderStatus:     foStatusListe,
      offeneShopifyPositionen:    pool.filter(p => p.rest > 0).length,
      shopifySkus:                [...skusInFo],
      shopifyFoPositionen:        foPosAlle,
      anzahlFoPositionen:         foPosAlle.length,
      anzahlFoPositionenOhneSku:  foPosAlle.filter(p => !p.sku).length,
      normSchluesselGesperrt:     config.skuMatching ? [] : [...normGesperrt],
      matchingModus:              config.skuMatching ? 'sku' : 'titel'
    };
    const skip = (status, message) => out.push({ json: { ...basis,
      shopifyAktion: 'skip', shopifyStatus: status, shopifyMessage: message,
      zuordnung: [], summeGeliefert: ls.positionen.reduce((s, p) => s + p.mengeGeliefert, 0),
      summeZugeordnet: 0, lineItemsByFulfillmentOrder: [], matchStufen: [] } });

    if (order.cancelledAt) { skip('skipped_cancelled', 'Bestellung in Shopify storniert'); continue; }

    if (ls.trackingNummer && trackingVorhanden.has(normSku(ls.trackingNummer))) {
      skip('skipped_already_shipped',
           'Trackingnummer ' + ls.trackingNummer + ' ist in Shopify bereits hinterlegt');
      continue;
    }

    // ---- Positionsweise zuordnen ------------------------------------
    const zuordnung = [];
    const perFo     = new Map();

    for (const p of ls.positionen) {
      // Ignorierte Positionen gar nicht erst zuordnen. mengeOffenGeblieben
      // bleibt 0, damit daraus keine Teilzuordnungs-Warnung entsteht.
      if (istIgnoriert(p.cArtNr)) {
        zuordnung.push({
          cArtNr:              p.cArtNr,
          cArtikelname:        p.cArtikelname,
          mengeGeliefert:      p.mengeGeliefert,
          mengeZugeordnet:     0,
          mengeOffenGeblieben: 0,
          mengeIgnoriert:      Math.round(Number(p.mengeGeliefert) || 0),
          status:              'ignoriert_kein_shopify_artikel',
          stufen:              [],
          titelWuerdePassen:   false,
          aehnlicheTitel:      null,
          treffer:             []
        });
        continue;
      }

      const pSku   = normSku(p.cArtNr);
      const pExakt = titelExakt(p.cArtikelname);
      const pNorm  = titelNorm(p.cArtikelname);

      // Aktive Stufen ergeben sich aus config.skuMatching.
      const stufen = config.skuMatching
        ? [ { name: 'sku',         passt: k => !!pSku   && !!k.sku    && k.sku    === pSku } ]
        : [ { name: 'titel_exakt', passt: k => !!pExakt && !!k.tExakt && k.tExakt === pExakt },
            { name: 'titel_norm',  passt: k => !!pNorm  && !!k.tNorm  && k.tNorm  === pNorm
                                               && !normGesperrt.has(pNorm) } ];

      let offen = Math.round(Number(p.mengeGeliefert) || 0);
      const treffer    = [];
      const stufenUsed = [];

      for (const stufe of stufen) {
        if (offen <= 0) break;
        for (const k of pool) {
          if (offen <= 0) break;
          if (k.rest <= 0 || !stufe.passt(k)) continue;
          const n = Math.min(offen, k.rest);
          k.rest -= n;
          offen  -= n;
          treffer.push({ fulfillmentOrderId: k.foId, fulfillmentOrderLineItemId: k.foliId,
                         menge: n, stufe: stufe.name, shopifyTitel: k.titel });
          if (!stufenUsed.includes(stufe.name)) stufenUsed.push(stufe.name);
          if (!perFo.has(k.foId)) perFo.set(k.foId, []);
          perFo.get(k.foId).push({ id: k.foliId, quantity: n });
        }
      }

      // Diagnose bei Nichttreffern – NIE zum Zuordnen verwendet, nur protokolliert.
      let aehnlich = null;
      if (!treffer.length && pNorm) {
        const kand = pool.filter(k => k.tNorm &&
          (k.tNorm.includes(pNorm) || pNorm.includes(k.tNorm)));
        if (kand.length) aehnlich = kand.map(k => k.titel);
      }
      // Im sku-Modus: haette der Titel gepasst? Zeigt den Pflegefortschritt an.
      const titelWuerdePassen = (config.skuMatching && !treffer.length && !!pExakt)
        ? pool.some(k => k.rest > 0 && k.tExakt === pExakt)
        : false;

      const zugeordnet = Math.round(Number(p.mengeGeliefert) || 0) - offen;
      let pStatus;
      if (zugeordnet > 0 && offen === 0)        pStatus = 'ok';
      else if (zugeordnet > 0)                  pStatus = 'teilweise';
      else if (config.skuMatching) {
        if (!pSku)                              pStatus = 'jtl_ohne_artikelnummer';
        else if (titelWuerdePassen)             pStatus = 'sku_fehlt_titel_wuerde_passen';
        else if (skusInFo.has(pSku))            pStatus = 'kein_rest_offen';
        else                                    pStatus = 'sku_nicht_in_shopify';
      } else {
        if (normGesperrt.has(pNorm))            pStatus = 'titel_mehrdeutig';
        else if (aehnlich)                      pStatus = 'titel_nur_aehnlich';
        else                                    pStatus = 'titel_nicht_gefunden';
      }

      zuordnung.push({
        cArtNr:              p.cArtNr,
        cArtikelname:        p.cArtikelname,
        mengeGeliefert:      p.mengeGeliefert,
        mengeZugeordnet:     zugeordnet,
        mengeOffenGeblieben: offen,
        status:              pStatus,
        stufen:              stufenUsed,
        titelWuerdePassen,
        aehnlicheTitel:      aehnlich,
        treffer
      });
    }

    const summeGeliefert  = zuordnung.reduce((s, z) => s + (Number(z.mengeGeliefert) || 0), 0);
    const summeZugeordnet = zuordnung.reduce((s, z) => s + z.mengeZugeordnet, 0);
    const summeIgnoriert  = zuordnung.reduce((s, z) => s + (Number(z.mengeIgnoriert) || 0), 0);
    const nurIgnorierte   = zuordnung.length > 0 &&
                            zuordnung.every(z => z.status === 'ignoriert_kein_shopify_artikel');
    const matchStufen     = [...new Set(zuordnung.flatMap(z => z.stufen))];
    const lineItemsByFulfillmentOrder = [...perFo.entries()]
      .map(([foId, items]) => ({ fulfillmentOrderId: foId, fulfillmentOrderLineItems: items }));

    // ---- Entscheidung ----------------------------------------------
    let status, aktion, msg = null;
    if (summeZugeordnet > 0) {
      const teil = zuordnung.some(z => z.mengeOffenGeblieben > 0);
      status = config.dryRun ? 'ready_dry_run' : 'ready';
      aktion = config.dryRun ? 'dry_run' : 'create';
      if (teil) msg = 'TEILZUORDNUNG – nicht alle Lieferscheinpositionen konnten zugeordnet werden';
      if (matchStufen.includes('titel_norm')) {
        msg = (msg ? msg + ' | ' : '') +
              'Treffer nur ueber normalisierten Titel – pruefen';
      }
    } else if (nurIgnorierte) {
      status = 'skipped_nur_ignorierte_positionen';
      aktion = 'skip';
      msg    = 'Lieferschein enthaelt ausschliesslich Positionen ohne Shopify-Entsprechung';
    } else if (order.displayFulfillmentStatus === 'FULFILLED') {
      status = 'skipped_already_fulfilled';
      aktion = 'skip';
      msg    = 'Bestellung in Shopify bereits vollstaendig versendet';
    } else if (!pool.length) {
      status = 'skipped_no_open_lineitems';
      aktion = 'skip';
      msg    = 'Keine offene FulfillmentOrder-Position (Status: ' + order.displayFulfillmentStatus + ')';
    } else {
      status = 'skipped_no_match';
      aktion = 'skip';
      msg    = config.skuMatching
        ? (zuordnung.some(z => z.titelWuerdePassen)
            ? 'Keine sku zuordenbar – Titel wuerde passen, sku in Shopify noch nicht gepflegt'
            : 'Keine Position ueber sku zuordenbar')
        : 'Keine Position ueber den Titel zuordenbar';
    }

    out.push({ json: { ...basis,
      shopifyAktion: aktion, shopifyStatus: status, shopifyMessage: msg,
      zuordnung, summeGeliefert, summeZugeordnet, summeIgnoriert, matchStufen,
      lineItemsByFulfillmentOrder } });
  }
}

return out;

// Body fuer fulfillmentCreate – positionsgenau, ein Call pro Lieferschein.
// WICHTIG: Node-Modus = "Run Once for Each Item".
// Im Modus "Run Once for All Items" wuerde nur der ERSTE Lieferschein eines
// Batches gemeldet und alle weiteren stillschweigend verworfen.
const config = $('Config').first().json.config;
const item   = $input.item.json;

// --- Versanddienstleister am Format der Sendungsnummer bestimmen --------
// Grund: JTL liefert in cAmazonCarrierCode pauschal 'DHL'; Shopify macht
// daraus "DHL Express" und verlinkt ins falsche Portal.
const erkenneCarrier = (nummer) => {
  const nr = String(nummer ?? '').trim();
  for (const regel of (config.carrierRegeln || [])) {
    let re;
    try { re = new RegExp(regel.muster); } catch (e) { continue; }   // kaputtes Muster ueberspringen
    if (re.test(nr)) {
      return {
        company: regel.company,
        url:     regel.urlVorlage ? regel.urlVorlage.replace('{nr}', encodeURIComponent(nr)) : null,
        regel:   regel.name
      };
    }
  }
  return {
    company: item.trackingCarrier || config.carrierFallbackCompany || 'DHL',
    url:     null,
    regel:   'fallback'
  };
};

const fulfillment = {
  notifyCustomer: config.notifyCustomer,
  lineItemsByFulfillmentOrder: item.lineItemsByFulfillmentOrder
};

let carrier = null;
if (config.trackingSenden && item.trackingNummer) {
  carrier = erkenneCarrier(item.trackingNummer);
  fulfillment.trackingInfo = {
    number:  item.trackingNummer,
    company: carrier.company
  };
  // Explizite URL schlaegt Shopifys eigene Zuordnung.
  if (carrier.url) fulfillment.trackingInfo.url = carrier.url;
}

const body = {
  query: `mutation fulfillmentCreate($fulfillment: FulfillmentInput!) {
    fulfillmentCreate(fulfillment: $fulfillment) {
      fulfillment {
        id
        status
        createdAt
        totalQuantity
        trackingInfo(first: 5) { number company url }
      }
      userErrors { field message }
    }
  }`,
  variables: { fulfillment }
};

return { json: { ...item,
  carrierRegel:   carrier ? carrier.regel   : null,
  carrierCompany: carrier ? carrier.company : null,
  carrierUrl:     carrier ? carrier.url     : null,
  gqlBody: JSON.stringify(body) } };

// Antwort von fulfillmentCreate auswerten.
// WICHTIG: Node-Modus = "Run Once for Each Item" – passend zum vorgelagerten
// HTTP-Node, der pro Lieferschein einmal feuert.
const src  = $('⚠️ Query bauen (fulfillmentCreate)').item.json;
const resp = $input.item.json;

const nutzlast   = resp?.data?.fulfillmentCreate ?? null;
const userErrors = nutzlast?.userErrors ?? [];

// Transportfehler oder GraphQL-Fehler auf Anfrageebene
if (resp?.error || resp?.errors) {
  return { json: { ...src,
    shopifyStatus:  'error',
    shopifyMessage: JSON.stringify(resp.error || resp.errors).slice(0, 500) } };
}

// Fachliche Ablehnung durch Shopify
if (userErrors.length) {
  return { json: { ...src,
    shopifyStatus:  'error',
    shopifyMessage: userErrors.map(e =>
      (Array.isArray(e.field) ? e.field.join('.') : e.field ?? '') + ': ' + e.message
    ).join(' | ').slice(0, 500) } };
}

const ff = nutzlast?.fulfillment ?? null;

if (!ff) {
  return { json: { ...src,
    shopifyStatus:  'error',
    shopifyMessage: 'Keine Fulfillment-Daten in der Antwort' } };
}

return { json: { ...src,
  shopifyStatus:          'done',
  shopifyMessage:         null,
  shopifyFulfillmentId:   ff.id ?? null,
  shopifyFulfillmentStat: ff.status ?? null,
  shopifyFulfillmentZeit: ff.createdAt ?? null,
  shopifyTrackingGesetzt: (ff.trackingInfo ?? []).map(t => t.number).join(', ') || null,
  shopifyTrackingUrl:     (ff.trackingInfo ?? [])[0]?.url ?? null } };

// PATH B – Schritt 1: Wer kommt fuer Mollie in Frage?
// Eingang: 'Debug-Tabelle' – Path A ist an dieser Stelle KOMPLETT durch.
const config = $('Config').first().json.config;
const zeilen = $input.all().map(i => i.json).filter(z => z && z.cLieferscheinNr);

// Whitelist von Path B (unabhaengig von der aus Path A)
const weiss = (config.mollieNurBestellnummern || [])
  .map(v => String(v ?? '').trim()).filter(Boolean);
const erlaubt = weiss.length ? new Set(weiss) : null;

const basis = z => ({
  // Herkunft aus Path A
  bestellnummer:    z.bestellnummer,
  kBestellung:      z.kBestellung,
  cLieferscheinNr:  z.cLieferscheinNr,
  kLieferschein:    z.kLieferschein,
  versendetAm:      z.versendetAm,
  trackingNummer:   z.trackingNummer,
  carrierCompany:   z.carrierCompany ?? null,
  carrierUrl:       z.carrierUrl ?? null,
  positionen:       z._positionen || z.positionen || [],
  mollieId:         z.mollieId ?? null,
  mollieExpiresAt:  z.mollieExpiresAt ?? null,
  restfristTage:    z.restfristTage ?? null,
  shopifyEntscheidung: z.entscheidung,
  runId:            z.runId
});

return zeilen.map(z => {
  const b = basis(z);

  if (!config.mollieAktiv) {
    return { json: { ...b, mollieAktion: 'skip', mollieStatus: 'deaktiviert',
      mollieMessage: 'config.mollieAktiv = false' } };
  }
  if (erlaubt && !erlaubt.has(String(b.bestellnummer))) {
    return { json: { ...b, mollieAktion: 'skip', mollieStatus: 'skipped_nicht_in_whitelist',
      mollieMessage: null } };
  }
  if (!(config.mollieShopifyOk || []).includes(z.entscheidung)) {
    return { json: { ...b, mollieAktion: 'skip', mollieStatus: 'skipped_kein_shopify_erfolg',
      mollieMessage: 'Shopify-Ergebnis: ' + z.entscheidung } };
  }
  if (!b.positionen.length) {
    return { json: { ...b, mollieAktion: 'skip', mollieStatus: 'skipped_keine_positionen',
      mollieMessage: 'Keine JTL-Positionen im Item' } };
  }

  // Rueckwirkend: die ord_-ID kommt aus dem Scan (Phase 1),
  // eine Zuordnungstabelle wird hier NICHT gebraucht.
  if (!b.mollieId) {
    return { json: { ...b, mollieAktion: 'skip', mollieStatus: 'offen_keine_mollie_id',
      mollieMessage: 'Kandidat ohne ord_-ID – sollte rueckwirkend nicht vorkommen' } };
  }

  return { json: { ...b, mollieAktion: 'lesen', mollieStatus: 'id_gefunden',
    mollieMessage: null } };
});

// URL fuer den GET-Call. Ohne ID wird nichts gelesen.
const config = $('Config').first().json.config;
const j = $input.item.json;
return { json: { ...j,
  mollieUrl: j.mollieId ? (config.mollieBasisUrl + '/orders/' + j.mollieId) : null } };

// PATH B – KERN: Zuordnung JTL-Lieferscheinposition -> Mollie-Orderline.
// Node-Modus: "Run Once for Each Item" – Rueckgabe deshalb ein OBJEKT
// { json: ... }, KEIN Array. Ein Array fuehrt zu
// "A 'json' property isn't an object".
//
// Mollie antwortet mit Content-Type application/hal+json. n8n parst das nicht
// automatisch, sondern legt den Body als STRING in $json.data ab.
const config = $('Config').first().json.config;
// Ohne Schleife: das Ausgangsitem kommt direkt aus dem vorgelagerten
// Node. Die Paarungsaufloesung ueber einen Schleifenknoten entfaellt.
const src    = $('Mollie: URL bauen').item.json;
const roh    = $input.item.json;

// --- Antwort in ein Objekt bringen ------------------------------------
let resp = roh;
let parseFehler = null;
if (typeof roh?.data === 'string') {
  try { resp = JSON.parse(roh.data); }
  catch (e) { parseFehler = 'data war String, aber kein JSON: ' + e.message; }
} else if (roh?.data && typeof roh.data === 'object') {
  resp = roh.data;
}

const normSku = s => String(s ?? '').trim().toUpperCase();
const geld    = v => (v && v.value !== undefined) ? Number(v.value) : null;
const zahl    = v => Math.round(Number(v) || 0);

const istIgnoriert = artNr => {
  const a = normSku(artNr);
  if (!a) return false;
  return (config.ignorierteArtikelNr || [])
    .map(v => normSku(v)).filter(Boolean)
    .some(pre => a.startsWith(pre));
};

const raus = (status, message, extra) => ({ json: { ...src,
  mollieAktion: 'skip', mollieStatus: status, mollieMessage: message,
  mollieZuordnung: [], mollieLines: [],
  mollieSummeGeliefert:  (src.positionen || []).reduce((s, p) => s + (p.mengeGeliefert || 0), 0),
  mollieSummeZugeordnet: 0, ...(extra || {}) } });

// --- Fehler ------------------------------------------------------------
if (parseFehler || typeof resp?.status === 'number' || resp?.detail) {
  return raus('error', parseFehler ||
    [resp?.status, resp?.title, resp?.detail].filter(Boolean).join(' – '));
}

const orderStatus = resp?.status ?? null;

// --- Zustand der Order -------------------------------------------------
// authorized = nichts erfasst · shipping = teilweise erfasst
// paid/completed = erledigt · expired/canceled = nicht mehr moeglich
if (orderStatus === 'paid' || orderStatus === 'completed') {
  return raus('skipped_bereits_erfasst', 'Mollie-Status: ' + orderStatus,
              { mollieOrderStatus: orderStatus });
}
if (orderStatus === 'expired') {
  return raus('skipped_verfallen', 'Autorisierung verfallen – nicht mehr einziehbar',
              { mollieOrderStatus: orderStatus });
}
if (orderStatus === 'canceled') {
  return raus('skipped_storniert', 'Order in Mollie storniert',
              { mollieOrderStatus: orderStatus });
}
if (orderStatus !== 'authorized' && orderStatus !== 'shipping') {
  return raus('skipped_status_unerwartet', 'Mollie-Status: ' + (orderStatus ?? 'unbekannt'),
              { mollieOrderStatus: orderStatus });
}

// --- Versendbare Orderlines --------------------------------------------
const lines = Array.isArray(resp?.lines) ? resp.lines : [];

const pool = [];               // nur Produktzeilen
const versandZeilen = [];      // shipping_fee, gesondert behandelt
const skusInMollie = new Set();

for (const l of lines) {
  const rest = zahl(l.shippableQuantity);
  const eintrag = {
    id:    l.id,
    sku:   normSku(l.sku),
    name:  l.name ?? null,
    typ:   l.type ?? null,
    rest,
    status: l.status ?? null
  };
  if (eintrag.sku) skusInMollie.add(eintrag.sku);
  if (l.type === 'shipping_fee') { versandZeilen.push(eintrag); continue; }
  if (rest > 0) pool.push(eintrag);
}

if (!pool.length && !versandZeilen.some(v => v.rest > 0)) {
  return raus('skipped_nichts_versendbar',
              'Keine Orderline mit shippableQuantity > 0',
              { mollieOrderStatus: orderStatus });
}

// --- Positionsweise zuordnen -------------------------------------------
const zuordnung = [];
const lines_out = [];

const eintragen = (id, menge) => {
  const vorhanden = lines_out.find(x => x.id === id);
  if (vorhanden) vorhanden.quantity += menge;
  else lines_out.push({ id, quantity: menge });
};

for (const p of (src.positionen || [])) {
  // Versandartikel aus JTL: in Mollie gibt es dafuer die shipping_fee-Zeile,
  // die separat behandelt wird. Hier ueberspringen.
  if (istIgnoriert(p.cArtNr)) {
    zuordnung.push({ cArtNr: p.cArtNr, cArtikelname: p.cArtikelname,
      mengeGeliefert: p.mengeGeliefert, mengeZugeordnet: 0, mengeOffenGeblieben: 0,
      mengeIgnoriert: zahl(p.mengeGeliefert),
      status: 'ignoriert_kein_mollie_artikel', treffer: [] });
    continue;
  }

  const sku = normSku(p.cArtNr);
  let offen = zahl(p.mengeGeliefert);
  const treffer = [];

  for (const k of pool) {
    if (offen <= 0) break;
    if (k.rest <= 0 || !k.sku || k.sku !== sku) continue;
    const n = Math.min(offen, k.rest);
    k.rest -= n;
    offen  -= n;
    treffer.push({ orderlineId: k.id, menge: n, mollieName: k.name });
    eintragen(k.id, n);
  }

  const zugeordnet = zahl(p.mengeGeliefert) - offen;
  let pStatus;
  if (zugeordnet > 0 && offen === 0)   pStatus = 'ok';
  else if (zugeordnet > 0)             pStatus = 'teilweise';
  else if (!sku)                       pStatus = 'jtl_ohne_artikelnummer';
  else if (skusInMollie.has(sku))      pStatus = 'kein_rest_versendbar';
  else                                 pStatus = 'sku_nicht_in_mollie';

  zuordnung.push({
    cArtNr: p.cArtNr, cArtikelname: p.cArtikelname,
    mengeGeliefert: p.mengeGeliefert,
    mengeZugeordnet: zugeordnet,
    mengeOffenGeblieben: offen,
    status: pStatus,
    treffer
  });
}

// --- Versandkosten ------------------------------------------------------
// Mollie fuehrt Versand als eigene Orderline. Wird sie nie gemeldet, bleibt
// der Versandbetrag dauerhaft unerfasst. Regel ueber config steuerbar:
//   'bei_letzter_lieferung' -> nur wenn danach keine Produktzeile mehr offen ist
//   'immer'                 -> bei jeder Meldung (Vorsicht bei Teillieferungen)
//   'nie'                   -> nie
const regel = config.mollieVersandkosten || 'bei_letzter_lieferung';
const produktRestNachher = pool.reduce((s, k) => s + Math.max(0, k.rest), 0);
let versandGemeldet = 0;

if (lines_out.length && regel !== 'nie') {
  const jetztVersand = regel === 'immer' || produktRestNachher === 0;
  if (jetztVersand) {
    for (const v of versandZeilen) {
      if (v.rest > 0) { eintragen(v.id, v.rest); versandGemeldet += v.rest; }
    }
  }
}

const summeGeliefert  = zuordnung.reduce((s, z) => s + (Number(z.mengeGeliefert) || 0), 0);
const summeZugeordnet = zuordnung.reduce((s, z) => s + z.mengeZugeordnet, 0);
const nurIgnorierte   = zuordnung.length > 0 &&
                        zuordnung.every(z => z.status === 'ignoriert_kein_mollie_artikel');

// --- Entscheidung -------------------------------------------------------
let status, aktion, msg = null;

if (summeZugeordnet > 0) {
  const teil = zuordnung.some(z => z.mengeOffenGeblieben > 0);
  status = config.mollieDryRun ? 'ready_dry_run' : 'ready';
  aktion = config.mollieDryRun ? 'dry_run' : 'send';
  if (teil) msg = 'TEILZUORDNUNG – nicht alle Lieferscheinpositionen zuordenbar';
} else if (nurIgnorierte) {
  status = 'skipped_nur_ignorierte_positionen';
  aktion = 'skip';
  msg    = 'Lieferschein enthaelt nur Positionen ohne Mollie-Entsprechung';
} else {
  // Unterscheiden, WARUM nichts zugeordnet wurde:
  //   'kein_rest_versendbar' = Position existiert in Mollie, ist aber schon
  //   gemeldet (shippableQuantity 0). Das ist ERLEDIGT, kein Datenproblem.
  //   Nur ein echter Nichttreffer ueber die sku ist 'skipped_no_match'.
  const alleErledigt = zuordnung.length > 0 &&
    zuordnung.every(z => z.status === 'kein_rest_versendbar' ||
                         z.status === 'ignoriert_kein_mollie_artikel');

  if (alleErledigt) {
    status = 'skipped_bereits_gemeldet';
    aktion = 'skip';
    msg    = 'Alle Positionen bereits gemeldet (shippableQuantity 0)';
  } else {
    status = 'skipped_no_match';
    aktion = 'skip';
    msg    = 'Keine Position ueber die sku zuordenbar';
  }
}

return { json: { ...src,
  mollieOrderStatus:     orderStatus,
  mollieBetrag:          geld(resp?.amount),
  mollieBereitsErfasst:  geld(resp?.amountCaptured),
  mollieExpiresAt:       resp?.expiresAt ?? null,
  mollieMethod:          resp?.method ?? null,
