// Body fuer POST /v2/orders/{id}/shipments.
// Node-Modus: "Run Once for Each Item".
//
// Verifiziert an docs.mollie.com/reference/create-shipment:
//   lines[]  – die zu versendenden Orderlines. Leer = alle offenen.
//   tracking – optional, Objekt mit carrier / code / url.
// Wir geben lines IMMER explizit an, weil Teillieferungen der Normalfall sind.
const config = $('Config').first().json.config;
const item   = $input.item.json;

const body = { lines: item.mollieLines };

if (config.mollieTrackingSenden && item.trackingNummer) {
  body.tracking = {
    carrier: item.carrierCompany || config.carrierFallbackCompany || 'DHL',
    code:    item.trackingNummer
  };
  if (item.carrierUrl) body.tracking.url = item.carrierUrl;
}

return { json: { ...item,
  mollieRequestUrl: config.mollieBasisUrl + '/orders/' + item.mollieId + '/shipments',
  mollieBody: JSON.stringify(body) } };

// Antwort von POST /shipments auswerten.
// Node-Modus: "Run Once for Each Item".
const src = $('⚠️ Mollie: Body bauen').item.json;
const roh = $input.item.json;

let resp = roh, parseFehler = null;
if (typeof roh?.data === 'string') {
  try { resp = JSON.parse(roh.data); }
  catch (e) { parseFehler = 'Antwort war String, aber kein JSON: ' + e.message; }
} else if (roh?.data && typeof roh.data === 'object') {
  resp = roh.data;
}

// Mollie meldet Fehler mit status als ZAHL plus title/detail.
if (parseFehler || typeof resp?.status === 'number' || resp?.detail) {
  return { json: { ...src,
    mollieStatus:  'error',
    mollieMessage: parseFehler ||
      [resp?.status, resp?.title, resp?.detail].filter(Boolean).join(' – ') } };
}

if (!resp?.id) {
  return { json: { ...src, mollieStatus: 'error',
    mollieMessage: 'Keine Shipment-Daten in der Antwort' } };
}

return { json: { ...src,
  mollieStatus:      'done',
  mollieMessage:     null,
  mollieShipmentId:  resp.id,
  mollieShipmentZeit: resp.createdAt ?? null,
  mollieShipmentLines: (resp.lines ?? []).length } };

// Auswertung ueber beide Pfade.
const config = $('Config').first().json.config;
const zeilen = $input.all().map(i => i.json).filter(z => z && z.cLieferscheinNr);

const kandidaten = $('Kandidaten aufbereiten').all().map(i => i.json);
const scan = kandidaten[0] || {};

const zaehl = (fn) => {
