};
const summe = arr => Math.round(arr.reduce((s, z) => s + (Number(z.mollieBetrag) || 0), 0) * 100) / 100;

const mollieMeldbar  = zeilen.filter(z => z.wuerdeMelden === 'JA');
const bestellungen   = new Set(zeilen.map(z => z.bestellnummer));
const eilig          = zeilen.filter(z => z.restfristTage !== null && z.restfristTage <= 30);

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const tab = (obj) => '<table border="1" cellpadding="4" cellspacing="0">' +
  Object.entries(obj).sort((a,b) => b[1]-a[1])
