  '</table>';

const spalten = ['bestellnummer','cLieferscheinNr','versendetAm','shopifyEntscheidung',
                 'mollieOrderStatus','positionenJTL','zuordnung','wuerdeMelden',
                 'entscheidung','restfristTage','hinweis'];
const kopf = '<tr>' + spalten.map(s => '<th align="left">' + s + '</th>').join('') + '</tr>';
const body = zeilen.slice(0, 200).map(z =>
  '<tr>' + spalten.map(s => '<td>' + esc(z[s]) + '</td>').join('') + '</tr>').join('');

const zusammenfassung = {
